export type ParkSlug = 'tadoba' | 'pench' | 'bandhavgarh' | 'kanha' | 'satpura' | 'panna' | 'tipeshwar' | 'umred-karhandla';

interface RawResort {
  id: string;
  name: string;
  park: ParkSlug;
  zone: string | null;
  address: string | null;
  lat: number | null;
  lng: number | null;
  googleRating: number | null;
  googleReviewCount: number | null;
  googleMapsUrl: string | null;
  ratingCheckedAt: string | null;
  rooms: string[];
  photos: number;
}

export interface ResortArea {
  key: string;
  label: string;
  /** reads after the resort name: "X is a resort {phrase} Tadoba-Andhari Tiger Reserve" */
  phrase: string;
  blurb?: string;
  gates?: string;
  /** existing editorial guide for this area, if the site has one */
  guideHref?: string;
}

export interface Park {
  slug: ParkSlug;
  name: string;
  fullName: string;
  state: string;
  airport: string;
  /** where "all resorts in this park" lives: an editorial guide, or the generated park page */
  listingHref: string;
  listingLabel: string;
  hasDirectoryPage: boolean;
  toursHref: string;
  bookingHref?: string;
  parkHref?: string;
  areas: ResortArea[];
  photo: { src: ImageMetadata; alt: string };
}

export interface ResortPhoto { src: ImageMetadata; alt: string }

export interface DirectoryResort extends RawResort {
  slug: string;
  path: string;
  parkInfo: Park;
  area: ResortArea;
  photoList: ResortPhoto[];
  /** checked facts from the site's park resort guides, when this property is in them */
  verified?: { guideName: string; category: ResortCategory; location: string; highlights: string; website?: string };
  facts: ResortFacts;
  /** straight-line distance from the Google Maps pin to the mapped gate for this resort's area */
  gate?: { name: string; km: number };
}

const tadobaAreas: ResortArea[] = (['kolara', 'moharli', 'navegaon', 'pangdi-zari'] as const).map((key) => {
  const z = tadobaGuideZones.find((item) => item.key === key)!;
  const label = z.name.replace(/ \(.*\)$/, '') + ' zone';
  return {
    key,
    label,
    phrase: `in the ${label} of`,
    blurb: z.blurb,
    gates: z.gates,
    guideHref: key === 'kolara' ? '/resorts-near-kolara-gate-tadoba/' : key === 'moharli' ? '/resorts-near-moharli-gate-tadoba/' : undefined,
  };
});
