/** areas inside Pench and Bandhavgarh come from each resort's Google address, not the reference document */
function areaKey(r: RawResort): string {
  if (r.park === 'tadoba') return r.zone === 'Pangdi & Zari' ? 'pangdi-zari' : (r.zone ?? 'moharli').toLowerCase();
  if (r.park === 'pench') {
    if (r.id === 'rukhad-jungle-camp') return 'rukhad';
    if (/Maharashtra/.test(r.address ?? '')) return 'maharashtra';
    return 'turia';
  }
  if (r.park === 'kanha') return (r.zone ?? 'khatia').toLowerCase();
  if (r.park === 'satpura') return (r.zone ?? 'madhai').toLowerCase();
  return parks.find((p) => p.slug === r.park)!.areas[0].key;
}

