function photosFor(id: string, name: string): ResortPhoto[] {
  const cover = coverPhoto[id] && `/${coverPhoto[id]}.webp`;
  return Object.entries(photoModules)
    .filter(([file]) => file.includes(`/resorts/${id}/`))
    .sort(([a], [b]) => Number(cover && b.endsWith(cover)) - Number(cover && a.endsWith(cover)) || a.localeCompare(b))
    .map(([, mod], i) => ({ src: mod.default, alt: i === 0 ? `${name}, main view` : `${name}, photo ${i + 1}` }));
}

const guideIndex = new Map(
  [...tadobaGuideResorts, ...penchGuideResorts].map((r) => [r.name, r]),
);

export const directory: DirectoryResort[] = (raw as RawResort[])
  .map((r) => {
    const parkInfo = parks.find((p) => p.slug === r.park)!;
    const key = areaKey(r);
    const area = parkInfo.areas.find((a) => a.key === key)!;
    const name = displayNames[r.id] ?? r.name;
    const guide = guideNames[r.id] ? guideIndex.get(guideNames[r.id]) : undefined;
    const gate = areaGates[key];
    const gateKm = gate && distanceKm(r, gate);
    return {
      ...r,
      name,
      slug: r.id,
      path: `/resorts/${r.park}/${r.id}/`,
      parkInfo,
      area,
      photoList: photosFor(r.id, name),
      verified: guide && { guideName: guide.name, category: guide.category, location: guide.location, highlights: guide.highlights, website: guide.website },
      facts: resortFacts[r.id] ?? {},
      gate: gate && gateKm != null ? { name: gate.name, km: gateKm } : undefined,
    };
  })
  .sort((a, b) => a.name.localeCompare(b.name));

export const resortsInPark = (park: ParkSlug) => directory.filter((r) => r.park === park);
export const resortsInArea = (park: ParkSlug, area: string) => directory.filter((r) => r.park === park && r.area.key === area);
export const parksWithResorts = parks.filter((p) => directory.some((r) => r.park === p.slug));

/** straight-line distance in km between two resorts, from their Google coordinates */
export function distanceKm(a: Pick<RawResort, 'lat' | 'lng'>, b: Pick<RawResort, 'lat' | 'lng'>): number | null {
  if (a.lat == null || a.lng == null || b.lat == null || b.lng == null) return null;
  const rad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
}

export function nearbyResorts(resort: DirectoryResort, limit = 4) {
  return directory
    .filter((r) => r.park === resort.park && r.id !== resort.id)
    .map((r) => ({ resort: r, km: distanceKm(resort, r) }))
    .filter((x): x is { resort: DirectoryResort; km: number } => x.km != null)
    .sort((a, b) => a.km - b.km)
    .slice(0, limit);
}

export const formatKm = (km: number) => (km < 1 ? `${Math.round(km * 1000)} m` : `${km.toFixed(1)} km`);

/** profile page for a property listed in the Tadoba/Pench guides, so guide cards can link to it */
export function profilePathForGuideName(guideName: string): string | undefined {
  return directory.find((r) => r.verified?.guideName === guideName)?.path;
}

export function formatCheckedDate(iso: string | null): string {
  return iso ? new Date(`${iso}T00:00:00`).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
}

/** most-reviewed resort first: a fair, data-backed order that doesn't imply a ranking of quality */
export const byReviewCount = (a: DirectoryResort, b: DirectoryResort) => (b.googleReviewCount ?? 0) - (a.googleReviewCount ?? 0);

/** 1-based position by Google review count among the resort's park */
export const reviewRank = (resort: DirectoryResort) => [...resortsInPark(resort.park)].sort(byReviewCount).findIndex((r) => r.id === resort.id) + 1;

export const ordinal = (n: number) => {
  const teen = n % 100 >= 11 && n % 100 <= 13;
  return `${n}${teen ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' } as Record<number, string>)[n % 10] ?? 'th'}`;
};

export const hasPool = (r: DirectoryResort) => (r.facts.facilities ?? []).some((f) => /pool/i.test(f));
